import{_ as p,a0 as o,w as r,s as d,I as a,x as i,a1 as t,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"一步步教你如何安装 Arch Linux | LCTT x X-CMD","titleTemplate":false,"description":"一步步教你如何安装 Arch Linux | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一步步教你如何安装 Arch Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一步步教你如何安装 Arch Linux | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171211 How to Install Arch Linux [Step by Step Guide]","title":"一步步教你如何安装 Arch Linux","tag":"201712","desc":""},"relativePath":"201712/20171211 How to Install Arch Linux [Step by Step Guide].md","filePath":"[post].md"}'),h={name:"201712/20171211 How to Install Arch Linux [Step by Step Guide].md"};function g(u,s,k,c,b,f){const e=o("Link");return r(),d("div",null,[s[42]||(s[42]=a("h1",{id:"一步步教你如何安装-arch-linux",tabindex:"-1"},[i("一步步教你如何安装 Arch Linux "),a("a",{class:"header-anchor",href:"#一步步教你如何安装-arch-linux","aria-label":"Permalink to “一步步教你如何安装 Arch Linux”"},"​")],-1)),s[43]||(s[43]=a("p",null,[a("img",{src:"https://itsfoss.com/wp-content/uploads/2017/12/install-arch-linux-featured-800x450.png",alt:"How to install Arch Linux"})],-1)),s[44]||(s[44]=a("blockquote",null,[a("p",null,"简要说明：这一教程会教你如何用简单步骤安装 Arch Linux。")],-1)),a("p",null,[t(e,{href:"https://www.archlinux.org/"},{default:n(()=>[...s[0]||(s[0]=[i("Arch Linux",-1)])]),_:1}),s[2]||(s[2]=i(" 是一个 x86-64 通用发行版，它流行于那些喜欢 ",-1)),t(e,{href:"https://en.wikipedia.org/wiki/Do_it_yourself"},{default:n(()=>[...s[1]||(s[1]=[i("DIY",-1)])]),_:1}),s[3]||(s[3]=i(" Linux 系统的用户和 Linux 铁杆粉丝当中。其默认的安装文件只含有一个最基本的系统，它希望使用者自己配置并使用 Arch 系统。其基于 KISS 原则（",-1)),s[4]||(s[4]=a("ruby",null,[i("使它保持简单、傻瓜"),a("rt",null,"Keep It Simple, Stupid!")],-1)),s[5]||(s[5]=i("），Arch Linux 是一个专注于优雅、代码正确，精简而简洁的系统。",-1))]),a("p",null,[s[7]||(s[7]=i("Arch 支持滚动发布模式，并且有自己的软件包管理器 —— ",-1)),t(e,{href:"https://wiki.archlinux.org/index.php/pacman"},{default:n(()=>[...s[6]||(s[6]=[i("pacman",-1)])]),_:1}),s[8]||(s[8]=i("。为了提供一个先锐的操作系统，Arch 绝不会错失任何一个最新的源。实际上，它只提供了一个最小化的基本操作系统，使得你可以在低端硬件上安装 Arch，并且只安装你所必须的软件包。",-1))]),s[45]||(s[45]=l('<p>同时，它也是最流行的从头开始学习 Linux 的操作系统之一。如果你想以 DIY 精神自己体验一番，你应该尝试一下 Arch Linux。 这被许多 Linux 用户视作核心的 Linux 体验。</p><p>在这篇文章里，我们会了解到如何安装、配置 Arch 并在其上安装桌面环境。</p><h3 id="如何安装-arch-linux" tabindex="-1">如何安装 Arch Linux <a class="header-anchor" href="#如何安装-arch-linux" aria-label="Permalink to “如何安装 Arch Linux”">​</a></h3><p>我们在这里讨论的安装方法是从你的电脑上<strong>完全删除已有的操作系统</strong> ，而后在其上安装 Arch Linux。如果你想遵循这一教程安装 Arch，请确保你已经备份了所有文件，否则你就会失去它们。切切。</p><p>在你从 USB 上安装 Arch 之前，请确保你已经满足了以下条件：</p><h4 id="安装-arch-linux-的条件" tabindex="-1">安装 Arch Linux 的条件： <a class="header-anchor" href="#安装-arch-linux-的条件" aria-label="Permalink to “安装 Arch Linux 的条件：”">​</a></h4><ul><li>一个兼容 x86_64（例如 64 位）的机器</li><li>最小 512M 内存（建议 2GB）</li><li>最少 1GB 的磁盘空余空间（日常使用推荐 20GB）</li><li>可以访问互联网</li><li>至少有 2GB 存储空间的 USB 存储器</li><li>熟悉 Linux 命令行</li></ul><p>一旦你确认满足所有条件，就可以开始安装 Arch Linux 了。</p><h4 id="第一步-下载-iso-文件" tabindex="-1">第一步：下载 ISO 文件 <a class="header-anchor" href="#第一步-下载-iso-文件" aria-label="Permalink to “第一步：下载 ISO 文件”">​</a></h4>',9)),a("p",null,[s[10]||(s[10]=i("你可以从",-1)),t(e,{href:"https://www.archlinux.org/download/"},{default:n(()=>[...s[9]||(s[9]=[i("官网",-1)])]),_:1}),s[11]||(s[11]=i("上下载 ISO。安装 Arch Linux 需要一个至少有 512M 内存和 800M 磁盘空间，并兼容 x86_64 （如 64 位）的机器。不过，建议至少有 2G 内存和 20G 磁盘空间，这样安装桌面环境时就不会遇到麻烦。",-1))]),s[46]||(s[46]=a("h4",{id:"第二步-创建一个-arch-linux-的现场版-usb-存储器",tabindex:"-1"},[i("第二步：创建一个 Arch Linux 的现场版 USB 存储器 "),a("a",{class:"header-anchor",href:"#第二步-创建一个-arch-linux-的现场版-usb-存储器","aria-label":"Permalink to “第二步：创建一个 Arch Linux 的现场版 USB 存储器”"},"​")],-1)),s[47]||(s[47]=a("p",null,[i("我们需要用你刚刚下载的 ISO 文件创建一个 Arch Linux 的"),a("ruby",null,[i("现场版"),a("rt",null,"live")]),i(" USB 存储器。")],-1)),a("p",null,[s[13]||(s[13]=i("如果你使用 Linux，你可以用 ",-1)),s[14]||(s[14]=a("code",null,"dd",-1)),s[15]||(s[15]=i(" 命令来创建现场版 USB 存储器。 记得将下面的例子中的 ",-1)),s[16]||(s[16]=a("code",null,"/path/to/archlinux.iso",-1)),s[17]||(s[17]=i(" 改成你的 ISO 文件的实际存储位置，",-1)),s[18]||(s[18]=a("code",null,"/dev/sdx",-1)),s[19]||(s[19]=i(" 改成你的磁盘设备号（例如 ",-1)),s[20]||(s[20]=a("code",null,"/dev/sdb",-1)),s[21]||(s[21]=i("）。你可以通过 ",-1)),t(e,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/6/html/deployment_guide/s1-sysinfo-filesystems"},{default:n(()=>[...s[12]||(s[12]=[i("lsblk",-1)])]),_:1}),s[22]||(s[22]=i(" 命令来了解你的设备信息。",-1))]),s[48]||(s[48]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd bs=4M if=/path/to/archlinux.iso of=/dev/sdx status=progress &amp;&amp; sync</span></span></code></pre></div>',1)),a("p",null,[s[24]||(s[24]=i("在 Windows 下，有多种方法来创建现场版 USB 存储器。 推荐工具是 Rufus。我们之前已经有",-1)),t(e,{href:"https://itsfoss.com/live-usb-antergos/"},{default:n(()=>[...s[23]||(s[23]=[i("如何使用这一工具创建Antergos 现场版 USB 存储器",-1)])]),_:1}),s[25]||(s[25]=i("的教程。因为 Antergos 发行版是基于 Arc h的，所以你可以使用同一教程。",-1))]),s[49]||(s[49]=l(`<h4 id="步骤三-从现场版-usb-存储器上启动" tabindex="-1">步骤三：从现场版 USB 存储器上启动 <a class="header-anchor" href="#步骤三-从现场版-usb-存储器上启动" aria-label="Permalink to “步骤三：从现场版 USB 存储器上启动”">​</a></h4><p>一旦你已经创建了 Arch Linux 的现场版 USB 存储器，关闭你的电脑。插上你的 USB 存储器然后启动系统。在开机启动时，持续按 F2、F10 或 F1 之类的按键（根据你的电脑型号而定）进入启动设置。在这里，选择“从 USB 存储器或可移除设备启动”这一项。</p><p>一旦你选择了它，你会看到这样一个选项：</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/11/1-2.jpg" alt="Arch Linux"></p><p>选择“Boot Arch Linux (x86_64)”。经过各种系统检查后，Arch Linux 会启动到 root 用户的命令行界面。</p><p>接下来的步骤包括磁盘分区、创建文件系统并挂载它。</p><h4 id="第四步-磁盘分区" tabindex="-1">第四步：磁盘分区 <a class="header-anchor" href="#第四步-磁盘分区" aria-label="Permalink to “第四步：磁盘分区”">​</a></h4><p>第一步就是给你的硬盘分区。单根分区是最简单的，就在它上面创建根分区（<code>/</code>）分区、交换分区和 <code>home</code> 分区。</p><p>我有一个 19G 的硬盘，我想在这儿安装 Arch Linux。为了创建分区，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk /dev/sda</span></span></code></pre></div><p>按 <code>n</code> 创建新分区。按 <code>p</code> 创建主分区，然后选择分区号。</p><p>第一个扇区会被自动选择，你只要按回车键。在确定分区的最后一个扇区时，请输入这一分区的大小。</p><p>用相同的方法为 <code>home</code> 和交换分区创建两个分区，按 <code>w</code> 来保存修改并退出。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/11/4-root-partition.png" alt="root partition"></p><h4 id="第四步-创建文件系统" tabindex="-1">第四步：创建文件系统 <a class="header-anchor" href="#第四步-创建文件系统" aria-label="Permalink to “第四步：创建文件系统”">​</a></h4><p>因为我们已经有了三个分区，接下来就是创建文件系统来格式化分区。</p><p>我们用 <code>mkfs</code> 命令在根分区和 <code>home</code> 分区上创建文件系统，用 <code>mkswap</code> 创建交换分区。我们用 ext4 文件系统格式化磁盘。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs.ext4 /dev/sda1</span></span>
<span class="line"><span>mkfs.ext4 /dev/sda3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mkswap /dev/sda2</span></span>
<span class="line"><span>swapon /dev/sda2</span></span></code></pre></div><p>将这些分区挂载在根分区和 <code>home</code> 分区下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount /dev/sda1 /mnt</span></span>
<span class="line"><span>mkdir /mnt/home</span></span>
<span class="line"><span>mount /dev/sda3 /mnt/home</span></span></code></pre></div><h4 id="第五步-安装" tabindex="-1">第五步：安装 <a class="header-anchor" href="#第五步-安装" aria-label="Permalink to “第五步：安装”">​</a></h4><p>我们已经创建分区并挂载了分区，开始安装最基本的软件包。基本的软件包包括了系统运行所必需的所有软件包。比如有 GNU BASH shell、文件压缩工具、文件系统管理工具、C 语言库、压缩工具、Linux 内核及其模块，类库、系统工具、USB 设备工具、Vi 文本编辑器等等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacstrap /mnt base base-devel</span></span></code></pre></div><h4 id="第六步-配置系统" tabindex="-1">第六步：配置系统 <a class="header-anchor" href="#第六步-配置系统" aria-label="Permalink to “第六步：配置系统”">​</a></h4><p>生成一个 <code>fstab</code> 文件来规定磁盘分区、块设备，或者远程文件系统是如何挂载进文件系统中的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>genfstab -U /mnt &gt;&gt; /mnt/etc/fstab</span></span></code></pre></div><p>进入 chroot 环境，这样可以为当前进程以及子进程切换当前根目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arch-chroot /mnt</span></span></code></pre></div><p>一些需要与数据总线保持连接的 systemd 工具不能在 chroot 环境下使用，所以需要从当前环境退出。想要退出 chroot，就用下面的命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><h4 id="第七步-设定时区" tabindex="-1">第七步：设定时区 <a class="header-anchor" href="#第七步-设定时区" aria-label="Permalink to “第七步：设定时区”">​</a></h4><p>用下面这条命令设定时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -sf /usr/share/&lt;时区信息&gt;/&lt;地区&gt;/&lt;城市&gt; /etc/localtime</span></span></code></pre></div><p>获取时区列表，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /usr/share/zoneinfo</span></span></code></pre></div><p>用 <code>hwclock</code> 命令设定硬件时钟：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hwclock --systohc --utc</span></span></code></pre></div><h4 id="第八步-设置地区" tabindex="-1">第八步：设置地区 <a class="header-anchor" href="#第八步-设置地区" aria-label="Permalink to “第八步：设置地区”">​</a></h4><p>文件 <code>/etc/locale.gen</code> 在注释里包含了所有地区和系统语言设置。用 Vi 打开它，然后去掉你希望选择语言前面的注释。 我选择了 <code>en_GB.UTF-8</code>。</p><p>现在用下面的命令在 <code>/etc</code> 文件夹里生成 关于地区的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locale-gen</span></span>
<span class="line"><span>echo LANG=en_GB.UTF-8 &gt; /etc/locale.conf</span></span>
<span class="line"><span>export LANG=en_GB.UTF-8</span></span></code></pre></div><h4 id="第九步-安装-bootloader-设置主机名和-root-密码" tabindex="-1">第九步 ：安装 bootloader，设置主机名和 root 密码 <a class="header-anchor" href="#第九步-安装-bootloader-设置主机名和-root-密码" aria-label="Permalink to “第九步 ：安装 bootloader，设置主机名和 root 密码”">​</a></h4><p>创建 <code>/etc/hostname</code> 文件 然后添加一个对应的主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.1.1 myhostname.localdomain myhostname</span></span></code></pre></div><p>我添加了 <code>ItsFossArch</code> 作为我的主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo ItsFossArch &gt; /etc/hostname</span></span></code></pre></div><p>然后也将它添加到 <code>/etc/hosts</code> 中</p><p>为了安装 bootloader 使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S grub</span></span>
<span class="line"><span>grub-install /dev/sda</span></span>
<span class="line"><span>grub-mkconfig -o /boot/grub/grub.cfg</span></span></code></pre></div><p>创建 root 密码，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd</span></span></code></pre></div><p>输入你想要的密码。</p><p>完成之后，更新你的系统。但很有可能你的系统已经是最新的，因为你下载的是最新的 ISO。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Syu</span></span></code></pre></div><p>恭喜! 你已经安装了 Arch Linux 的命令行版本。</p><p>接下来，我们会了解到如何为 Arch 设置并安装一个桌面环境。我很喜欢 GNOME 桌面环境，所以在这儿也就选择了这个。</p><h4 id="第十步-安装桌面-这一例子中是-gnome" tabindex="-1">第十步：安装桌面（这一例子中是 GNOME） <a class="header-anchor" href="#第十步-安装桌面-这一例子中是-gnome" aria-label="Permalink to “第十步：安装桌面（这一例子中是 GNOME）”">​</a></h4><p>在你安装桌面之前，你需要先设置网络。</p><p>你可以用下面的命令看见你的端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2017/12/11.png" alt=""></p><p>在我的电脑上，端口名是 <code>enp0s3</code>。</p><p>将下面这一段加进文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/systemd/network/enp0s3.network</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Match]</span></span>
<span class="line"><span>name=en*</span></span>
<span class="line"><span>[Network]</span></span>
<span class="line"><span>DHCP=yes</span></span></code></pre></div><p>保存并退出。重启网络来应用你刚才的改动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart systemd-networkd</span></span>
<span class="line"><span>systemctl enable systemd-networkd</span></span></code></pre></div><p>将下面这两句话加进 <code>/etc/resolv.conf</code> 中</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 8.8.4.4</span></span></code></pre></div><p>下一步是安装 X 环境。</p><p>输入下面的命令安装 Xorg，并将它作为显示服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S xorg xorg-server</span></span></code></pre></div><p>gnome 包含了基本的 GNOME桌面，gnome-extra 则包含 GNOME 应用、归档管理器、磁盘管理器、文本编辑器和其它的应用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S gnome gnome-extra</span></span></code></pre></div><p>最后一步是在 Arch 上开启 GDM 显示管理器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start gdm.service</span></span>
<span class="line"><span>systemctl enable gdm.service</span></span></code></pre></div><p>重启你的系统，你就会看见 GNOME 的登录界面。</p><h3 id="arch-linux-安装总结" tabindex="-1">Arch Linux 安装总结 <a class="header-anchor" href="#arch-linux-安装总结" aria-label="Permalink to “Arch Linux 安装总结”">​</a></h3><p>我们在下面的视频中展示了一个由 Foss 读者 Gonzalo Tormo 提供的相似的安装方法（全屏观看，能更好的看清命令）：</p><p><img src="https://youtu.be/iENmRwVhsTQ" alt="视频"></p>`,79)),a("p",null,[s[27]||(s[27]=i("你也许意识到安装 Arch 不像",-1)),t(e,{href:"https://itsfoss.com/install-ubuntu-1404-dual-boot-mode-windows-8-81-uefi/"},{default:n(()=>[...s[26]||(s[26]=[i("安装 Ubuntu",-1)])]),_:1}),s[28]||(s[28]=i(" 一样简单。不过，只要有耐心，你一定可以安装好它，并且向全世界宣布你在用 Arch Linux。",-1))]),s[50]||(s[50]=a("p",null,"Arch Linux 安装过程本身就是一个学习的机会。一旦安装完毕，我建议你参考它的 Wiki 去尝试其它的桌面环境，从而更深入了解这一操作系统。你可以探索它，发现它的强大之处。",-1)),s[51]||(s[51]=a("p",null,"如果你在安装 Arch 的过程中遇到任何问题，请在评论中给我们留言。",-1)),s[52]||(s[52]=a("hr",null,null,-1)),a("p",null,[s[30]||(s[30]=i("via: ",-1)),t(e,{href:"https://itsfoss.com/install-arch-linux/"},{default:n(()=>[...s[29]||(s[29]=[i("https://itsfoss.com/install-arch-linux/",-1)])]),_:1})]),a("p",null,[s[34]||(s[34]=i("作者：",-1)),t(e,{href:"https://itsfoss.com/author/ambarish/"},{default:n(()=>[...s[31]||(s[31]=[i("Ambarish Kumar",-1)])]),_:1}),s[35]||(s[35]=i(" 译者：",-1)),t(e,{href:"https://github.com/wenwensnow"},{default:n(()=>[...s[32]||(s[32]=[i("wenwensnow",-1)])]),_:1}),s[36]||(s[36]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[33]||(s[33]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[39]||(s[39]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[37]||(s[37]=[i("LCTT",-1)])]),_:1}),s[40]||(s[40]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[38]||(s[38]=[i("Linux中国",-1)])]),_:1}),s[41]||(s[41]=i(" 荣誉推出",-1))])])}const v=p(h,[["render",g]]);export{y as __pageData,v as default};
